func statSub(d OverviewData) string {
	if d.MaxSandboxes > 0 {
		return "cap " + itoa(d.MaxSandboxes)
	}
	return "no cap"
}

func capacityClass(p int) string {
	switch {
	case p >= 90:
		return "[&_[data-slot=progress-indicator]]:bg-destructive"
	case p >= 70:
		return "[&_[data-slot=progress-indicator]]:bg-amber-500"
	default:
		return "[&_[data-slot=progress-indicator]]:bg-emerald-500"
	}
}

